function connectSession(session){if(!levels.length||isGenerating)throw Error('Wait for the dungeon to finish generating.');networkGame?.close();remoteInputs.clear();if(session.role==='host')for(const slot of session.connected){const hero=campaign.actor('hero-'+slot);remoteInputs.set(hero.id,{forward:0,strafe:0,yaw:hero.yaw,pitch:hero.pitch});}networkGame=createNetworkGame({session,getSnapshot:sessionSnapshot,onWorld:applyNetworkWorld,onState:applyNetworkState,onInput:(input,{actorId,disconnected})=>{if(disconnected){remoteInputs.delete(actorId);withHero(campaign.actor(actorId),()=>game.setGuard(false));}else{remoteInputs.set(actorId,input);const hero=campaign.actor(actorId);if(hero.offhand==='shield'&&hero.guarding!==input.blocking)withHero(hero,()=>game.setGuard(input.blocking));}},onAction:(kind,{actorId,targetId})=>['search-roll','search-close','take-item'].includes(kind)?remoteSearchAction(campaign.actor(actorId),kind,targetId):partyAction(campaign.actor(actorId),kind),onClass:(classId,{actorId})=>{if(campaign.state.phase!=='active'){campaign.setClass(actorId,classId);const hero=campaign.actor(actorId);hero.maxHealth=heroStats(hero).hp;if(hero.alive)hero.health=hero.maxHealth;}},onLoadout:(request,{actorId})=>{const hero=campaign.actor(actorId);if(request.slot)chooseLoadout(hero,request.slot,request.id);else{chooseLoadout(hero,'weapon',request.weapon);chooseLoadout(hero,'offhand',request.offhand);}},notify:toast});partyView.enabled=true;if(session.role==='guest'){document.body.classList.add('peer-guest');toast('Waiting for the host dungeon snapshot…');}else document.body.classList.remove('peer-guest');}
